// Asserts that two ASTs are structurally and content-wise equal.
void helper_assert_ast_equal(struct ASTNode *expected, struct ASTNode *actual) {
    if (expected == NULL && actual == NULL) return;
    assert((expected != NULL && actual != NULL) && "One ASTNode is NULL while the other is not");
    assert(expected->content == actual->content);
    helper_assert_ast_equal(expected->left, actual->left);
    helper_assert_ast_equal(expected->right, actual->right);
}

// Asserts that the NFA compiled from a regex accepts or rejects a string as expected.
void helper_assert_nfa_accepts(const char *regex, const char *string, int expected) {
    char *temp = preProcessing(regex);
    struct ASTNode *node = buildAST(temp);
    struct NFA *nfa = compileFromAST(node);
    postProcessing(nfa);
    nfa->currentStates = realloc(nfa->currentStates, sizeof(struct NFAState*) * 100);
    nfa->currentStates[nfa->CSCount++] = nfa->statePool[0];
    for (size_t i = 0; i < strlen(string); ++i) {
        transit(nfa, '\0');
        transit(nfa, string[i]);
    }
    transit(nfa, '\0');
    int result = isAccepting(nfa);
    assert(result == expected);
    destroyNFA(nfa);
    destroyNode(node);
    free(temp);
}

